// 1. Ambil data dari node sebelumnya (Code JavaScript cache)
// Kita ambil elemen pertama array-nya
const raw = $input.first().json;

// 2. Ambil body (tempat data summary berada)
const payload = raw.body || raw;

// 3. Ambil summary dengan pengaman
const summary = payload.summary || {};
const offlineAssets = payload.offline_assets || [];

// 4. Susun prompt untuk AI
const promptAI = `Kamu adalah AI Infrastructure Assistant untuk sistem T-AIMS.
Data Jaringan:
- Total Perangkat: ${summary.total_devices || 0}
- Online: ${summary.online || 0}
- Offline: ${summary.offline || 0}
- Availability: ${summary.availability_percent || 0}%

Perangkat Offline: 
${offlineAssets.length > 0 ? offlineAssets.map(a => a.asset_name).join(', ') : 'Tidak ada'}

Berikan analisis singkat (maksimal 2 paragraf) dan rekomendasi tindakan untuk teknisi.`;

// 5. Return data
return {
  json: {
    prompt_ai: promptAI
  }
};

// 1. Simpan waktu pemanggilan AI ke Cache
const staticData = $getWorkflowStaticData('global');
staticData.last_ai_call = Date.now();

// 2. Ambil data dari AI (HTTP Request)
const inputData = $input.first().json;
let teksAI = "Sistem AI (Gemini) sedang sibuk atau tidak merespons. Silakan periksa perangkat secara manual.";
let statusAI = "warning";

// 3. Cek apakah AI mengembalikan teks (format Google Gemini)
if (inputData.candidates && inputData.candidates[0]?.content?.parts[0]?.text) {
  teksAI = inputData.candidates[0].content.parts[0].text;
  statusAI = "critical"; // Anda bisa sesuaikan (misal: critical jika ada offline)
}

// 4. Simpan hasil AI ke Cache
staticData.last_ai_result = teksAI;

// 5. KEMBALIKAN FORMAT JSON WAJIB DZAKWAN
return {
  json: {
    status: statusAI, 
    status_network: statusAI === "critical" ? "KRITIS" : "PERINGATAN (WARNING)",
    device: "Cek detail di dashboard", 
    recommendation: teksAI
  }
};

const staticData = $getWorkflowStaticData('global');
const COOLDOWN_MS = 5 * 60 * 1000;
const now = Date.now();

const lastCall = staticData.last_ai_call || 0;
const lastResult = staticData.last_ai_result;

// Ambil data asli dari Webhook agar tidak hilang
const rawData = $input.first().json;

if (now - lastCall < COOLDOWN_MS && lastResult) {
  return [{ 
    json: { 
      isCached: "true", 
      ai_response: lastResult 
    } 
  }]; 
}

return [{ 
  json: { 
    isCached: "false",
    body: rawData.body // <--- INI KUNCINYA: Membawa data 15 ke node selanjutnya
  } 
}];
